(()=>{function refresh(){const l=SSStorage.read('spotsense-gto-v3.3')||SSStorage.read('spotsense-v3')||{},t=SSStorage.read('pokerTrainer_v1',{}),n=Number(t.stats?.totalHands)||0;document.getElementById('learn-count').textContent=Object.values(l.records||{}).filter(r=>r?.done).length+'/30';document.getElementById('train-count').textContent=n.toLocaleString();document.getElementById('train-accuracy').textContent=n?Math.round((t.stats.totalCorrect||0)/n*100)+'%':'尚無紀錄'}refresh();addEventListener('storage',refresh);addEventListener('pageshow',refresh)})();